import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("The same vendor name is allowed in a different tenant", { tag: "@VEN-04" }, async ({ apiAs }) => {
    // Arrange: a vendor with this name exists in tenant Globex Procurement
    const name = uniqueName("Acme Freight");
    const globex = await apiAs("otherTenant");
    const globexMe = await globex.get("/api/me");
    expect(globexMe.status(), await globexMe.text()).toBe(200);
    expect((await globexMe.json()).tenant.name).toBe("Globex Procurement");
    const existing = await globex.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });
    expect(existing.status(), await existing.text()).toBe(201);

    // Act: signed in as member@northwind.test, create a vendor with the same name
    const member = await apiAs("member");
    const res = await member.post("/api/vendors", {
      data: { name, category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    expect(res.status(), await res.text()).toBe(201);
    const created = await res.json();
    expect(created.name).toBe(name);
    expect(created.id).not.toBe((await existing.json()).id);
  });
});
